#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>
#include <Preferences.h>
#include <esp_netif.h>

Preferences prefs;
WebServer server(80);

const char* AP_SSID = "VALLIAN-REPEATER";
const char* AP_PASS = "12345678";

String homeSSID;
String homePASS;

bool natReady = false;

String page() {
  String status =
    WiFi.status() == WL_CONNECTED
      ? "CONNECTED TO " + WiFi.SSID()
      : "NOT CONNECTED";

  String nat =
    natReady
      ? "NAT ACTIVE"
      : "NAT NOT AVAILABLE";

  String html = R"HTML(
<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>VALLIAN Repeater</title>
<style>
body{
  background:#090908;
  color:#f5f1df;
  font-family:Arial,sans-serif;
  margin:0;
  padding:20px
}
.box{
  max-width:500px;
  margin:auto;
  background:#151510;
  padding:22px;
  border-radius:18px;
  border:1px solid #343022
}
h1{color:#f2c94c}
input,button{
  width:100%;
  box-sizing:border-box;
  padding:13px;
  margin:7px 0;
  border-radius:10px;
  border:1px solid #403b28;
  background:#0b0b09;
  color:white
}
button{
  background:#f2c94c;
  color:#111;
  font-weight:bold
}
small{color:#96917f}
.status{
  padding:10px;
  border-radius:10px;
  background:#211e12;
  margin-bottom:14px
}
</style>
</head>
<body>
<div class="box">

<h1>VALLIAN REPEATER</h1>

<div class="status">
)HTML";

  html += status;
  html += "<br>";
  html += nat;

  if (WiFi.status() == WL_CONNECTED) {
    html += "<br>IP: ";
    html += WiFi.localIP().toString();

    html += "<br>RSSI: ";
    html += String(WiFi.RSSI());
    html += " dBm";
  }

  html += R"HTML(
</div>

<h3>Wi-Fi Rumah</h3>

<form action="/save" method="POST">
<input name="ssid" placeholder="SSID Wi-Fi rumah">
<input name="pass" type="password" placeholder="Password">
<button type="submit">SAVE & CONNECT</button>
</form>

<h3>Firmware OTA</h3>

<form method="POST"
      action="/update"
      enctype="multipart/form-data">

<input type="file" name="firmware">
<button type="submit">UPLOAD .BIN</button>

</form>

<br>
<small>
Hotspot: VALLIAN-REPEATER<br>
IP panel: 192.168.4.1
</small>

</div>
</body>
</html>
)HTML";

  return html;
}

void connectHome() {
  if (homeSSID.length() == 0) return;

  WiFi.begin(
    homeSSID.c_str(),
    homePASS.c_str()
  );

  Serial.print("Connecting");

  for (int i = 0; i < 30; i++) {

    if (WiFi.status() == WL_CONNECTED)
      break;

    delay(500);
    Serial.print(".");
  }

  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {

    Serial.println("Connected");
    Serial.println(WiFi.localIP());

  } else {

    Serial.println("Connection failed");

  }
}

void enableNAT() {

  esp_netif_t* ap =
    esp_netif_get_handle_from_ifkey(
      "WIFI_AP_DEF"
    );

  if (!ap) {
    Serial.println("AP netif not found");
    natReady = false;
    return;
  }

  esp_err_t result =
    esp_netif_napt_enable(ap);

  if (result == ESP_OK) {

    natReady = true;
    Serial.println("NAPT enabled");

  } else {

    natReady = false;

    Serial.print("NAPT failed: ");
    Serial.println(
      esp_err_to_name(result)
    );
  }
}

void setupWeb() {

  server.on("/", HTTP_GET, []() {

    server.send(
      200,
      "text/html",
      page()
    );

  });

  server.on("/save", HTTP_POST, []() {

    homeSSID =
      server.arg("ssid");

    homePASS =
      server.arg("pass");

    prefs.putString(
      "ssid",
      homeSSID
    );

    prefs.putString(
      "pass",
      homePASS
    );

    server.send(
      200,
      "text/html",
      "<h2>Saved. Rebooting...</h2>"
    );

    delay(1000);
    ESP.restart();

  });

  server.on(
    "/update",
    HTTP_POST,

    []() {

      bool ok =
        !Update.hasError();

      server.send(
        200,
        "text/plain",
        ok
          ? "OTA SUCCESS. Rebooting..."
          : "OTA FAILED"
      );

      delay(1000);

      if (ok)
        ESP.restart();

    },

    []() {

      HTTPUpload& upload =
        server.upload();

      if (
        upload.status ==
        UPLOAD_FILE_START
      ) {

        Serial.printf(
          "OTA: %s\n",
          upload.filename.c_str()
        );

        Update.begin(
          UPDATE_SIZE_UNKNOWN
        );

      }

      else if (
        upload.status ==
        UPLOAD_FILE_WRITE
      ) {

        Update.write(
          upload.buf,
          upload.currentSize
        );

      }

      else if (
        upload.status ==
        UPLOAD_FILE_END
      ) {

        Update.end(true);

        Serial.printf(
          "OTA size: %u\n",
          upload.totalSize
        );
      }
    }
  );

  server.begin();
}

void setup() {

  Serial.begin(115200);

  prefs.begin(
    "repeater",
    false
  );

  homeSSID =
    prefs.getString(
      "ssid",
      ""
    );

  homePASS =
    prefs.getString(
      "pass",
      ""
    );

  WiFi.mode(
    WIFI_AP_STA
  );

  WiFi.softAP(
    AP_SSID,
    AP_PASS
  );

  Serial.print("AP IP: ");
  Serial.println(
    WiFi.softAPIP()
  );

  connectHome();

  delay(500);

  enableNAT();

  setupWeb();
}

void loop() {

  server.handleClient();

  static unsigned long lastCheck = 0;

  if (
    millis() - lastCheck >
    10000
  ) {

    lastCheck = millis();

    if (
      WiFi.status() !=
      WL_CONNECTED &&
      homeSSID.length()
    ) {

      WiFi.disconnect();
      connectHome();

      if (
        WiFi.status() ==
        WL_CONNECTED
      ) {
        enableNAT();
      }
    }
  }
}
